def _migrate_profile_sources() -> None:
    bind = op.get_bind()
    catalog = sa.table(
        "channels",
        sa.column("id", sa.String),
        sa.column("name", sa.String),
        sa.column("handle", sa.String),
        sa.column("topics", sa.String),
        sa.column("kind", sa.String),
        sa.column("is_recommended", sa.Boolean),
        sa.column("is_active", sa.Boolean),
        sa.column("meta", postgresql.JSONB),
    )
    op.bulk_insert(
        catalog,
        [
            {
                "id": item.id,
                "name": item.name,
                "handle": item.handle,
                "topics": item.topics,
                "kind": "catalog",
                "is_recommended": item.id in RECOMMENDED_IDS,
                "is_active": True,
                "meta": {},
            }
            for item in CHANNELS
        ],
    )
    insert_channel = sa.text(
        """
        INSERT INTO channels (id, name, handle, topics, kind, is_recommended, is_active, meta)
        VALUES (:id, :name, :handle, :topics, :kind, false, true, '{}'::jsonb)
        ON CONFLICT (id) DO NOTHING
        """
    )
    insert_subscription = sa.text(
        """
        INSERT INTO profile_channels (id, profile_id, channel_id, source)
        VALUES (:id, :profile_id, :channel_id, :source)
        ON CONFLICT (profile_id, channel_id) DO NOTHING
        """
    )
    rows = bind.execute(sa.text("SELECT id, sources FROM business_profiles")).mappings()
    for row in rows:
        raw = row["sources"]
        if isinstance(raw, str):
            try:
                sources = json.loads(raw)
            except json.JSONDecodeError:
                sources = {}
        else:
            sources = raw or {}
        channel_ids = [str(item) for item in sources.get("channels") or [] if item]
        custom = [item for item in sources.get("custom") or [] if isinstance(item, dict)]
        custom_ids = {str(item.get("id")) for item in custom if item.get("id")}
        for item in custom:
            channel_id = str(item.get("id") or "")
            if not channel_id:
                continue
            bind.execute(
                insert_channel,
                {
                    "id": channel_id,
                    "name": str(item.get("name") or channel_id),
                    "handle": item.get("handle"),
                    "topics": str(item.get("topics") or "добавлен вами"),
                    "kind": "custom",
                },
            )
        for channel_id in channel_ids:
            bind.execute(
                insert_channel,
                {
                    "id": channel_id,
                    "name": channel_id,
                    "handle": None,
                    "topics": "перенесено из профиля",
                    "kind": "catalog",
                },
            )
            bind.execute(
                insert_subscription,
                {
                    "id": str(uuid.uuid4()),
                    "profile_id": row["id"],
                    "channel_id": channel_id,
                    "source": "custom" if channel_id in custom_ids else "catalog",
                },
            )
        if channel_ids or custom:
            bind.execute(
                sa.text("UPDATE business_profiles SET sources_initialized = true WHERE id = :id"),
                {"id": row["id"]},
            )


